                    renderer: Ext.util.Format.numberRenderer('0'),
                    orientation: 'vertical',
                    color: '#333'
                },
                xField: 'name',
                yField: 'data'
            }
        ]
    });

In this configuration we set `{@link #cfg!column column}` as the series type, bind the values of the bars to the bottom axis,
set `{@link #cfg!highlight highlight}` to true so that bars are smoothly highlighted when hovered and bind the `{@link #cfg!xField xField}` or category
field to the data store `name` property and the `{@link #cfg!yField yField}` as the data1 property of a store element.

Creates a Gauge Chart. Gauge Charts are used to show progress in a certain variable. There are two ways of using the Gauge chart.
One is setting a store element into the Gauge and selecting the field to be used from that store. Another one is instantiating the
visualization and using the `{@link #method!setValue setValue}` method to adjust the value you want.

An example of Gauge visualization:

    @example
    var store = Ext.create('Ext.data.JsonStore', {
        fields: ['data'],
        data: [
            { 'value':80 }
        ]
    });

    Ext.create('Ext.chart.Chart', {
        renderTo: Ext.getBody(),
        store: store,
        width: 400,
        height: 250,
        animate: true,
        insetPadding: 30,
        axes: [{
            type: 'gauge',
            position: 'gauge',
            minimum: 0,
            maximum: 100,
            steps: 10,
            margin: 10
        }],
        series: [{
            type: 'gauge',
            field: 'value',
            donut: 30,
            colorSet: ['#F49D10', '#ddd']
        }]
    });

    Ext.widget("button", {
        renderTo: Ext.getBody(),
        text: "Refresh",
        handler: function() {
            store.getAt(0).set('value', Math.round(Math.random()*100));
        }
    });

In this example we create a special Gauge axis to be used with the gauge visualization (describing half-circle markers), and also we're
setting a maximum, minimum and steps configuration options into the axis. The Gauge series configuration contains the store field to be bound to
the visual display and the color set to be used with the visualization.

Creates a Line Chart. A Line Chart is a useful visualization technique to display quantitative information for different
categories or other real values (as opposed to the bar chart), that can show some progression (or regression) in the dataset.
As with all other series, the Line Series must be appended in the *series* Chart array configuration. See the Chart
documentation for more information. A typical configuration object for the line series could be:

    @example
    var store = Ext.create('Ext.data.JsonStore', {
        fields: ['name', 'data1', 'data2', 'data3', 'data4', 'data5'],
        data: [
            { 'name': 'metric one',   'data1': 10, 'data2': 12, 'data3': 14, 'data4': 8,  'data5': 13 },
            { 'name': 'metric two',   'data1': 7,  'data2': 8,  'data3': 16, 'data4': 10, 'data5': 3  },
            { 'name': 'metric three', 'data1': 5,  'data2': 2,  'data3': 14, 'data4': 12, 'data5': 7  },
            { 'name': 'metric four',  'data1': 2,  'data2': 14, 'data3': 6,  'data4': 1,  'data5': 23 },
            { 'name': 'metric five',  'data1': 4,  'data2': 4,  'data3': 36, 'data4': 13, 'data5': 33 }
        ]
    });

    Ext.create('Ext.chart.Chart', {
        renderTo: Ext.getBody(),
        width: 500,
        height: 300,
        animate: true,
        store: store,
        axes: [
            {
                type: 'Numeric',
                position: 'left',
                fields: ['data1', 'data2'],
                label: {
                    renderer: Ext.util.Format.numberRenderer('0,0')
                },
                title: 'Sample Values',
                grid: true,
                minimum: 0
            },
            {
                type: 'Category',
                position: 'bottom',
                fields: ['name'],
                title: 'Sample Metrics'
            }
        ],
        series: [
            {
                type: 'line',
                highlight: {
                    size: 7,
                    radius: 7
                },
                axis: 'left',
                xField: 'name',
                yField: 'data1',
                markerConfig: {
                    type: 'cross',
                    size: 4,
                    radius: 4,
                    'stroke-width': 0
                }
            },
            {
                type: 'line',
                highlight: {
                    size: 7,
                    radius: 7
                },
                axis: 'left',
                fill: true,
                xField: 'name',
                yField: 'data2',
                markerConfig: {
                    type: 'circle',
                    size: 4,
                    radius: 4,
                    'stroke-width': 0
                }
            }
        ]
