            { 'name': 'metric five',  'data1': 36, 'data2': 38, 'data3': 33 }
        ]
    });

    Ext.create('Ext.chart.Chart', {
        renderTo: Ext.getBody(),
        width: 500,
        height: 300,
        animate: true,
        theme:'Category2',
        store: store,
        axes: [{
            type: 'Radial',
            position: 'radial',
            label: {
                display: true
            }
        }],
        series: [{
            type: 'radar',
            xField: 'name',
            yField: 'data1',
            showInLegend: true,
